<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??$_POST['id']??0);$s=$pdo->prepare('SELECT * FROM catalogo_servicios WHERE id=?');$s->execute([$id]);$svc=$s->fetch();if(!$svc){http_response_code(404);exit('Servicio no encontrado');}
if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['add'])){$inv=(int)$_POST['inventario_id'];$cant=efloat('cantidad',1);if($inv&&$cant>0)$pdo->prepare('INSERT INTO catalogo_insumos(catalogo_id,inventario_id,cantidad) VALUES(?,?,?) ON DUPLICATE KEY UPDATE cantidad=VALUES(cantidad)')->execute([$id,$inv,$cant]);}if(isset($_POST['del']))$pdo->prepare('DELETE FROM catalogo_insumos WHERE id=? AND catalogo_id=?')->execute([(int)$_POST['row_id'],$id]);ego('receta.php?id='.$id);}
$inv=$pdo->query('SELECT * FROM inventario WHERE activo=1 ORDER BY nombre')->fetchAll();$st=$pdo->prepare('SELECT ci.*,i.nombre,i.unidad,i.stock,i.costo_unitario FROM catalogo_insumos ci JOIN inventario i ON i.id=ci.inventario_id WHERE ci.catalogo_id=? ORDER BY i.nombre');$st->execute([$id]);$rows=$st->fetchAll();?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Insumos · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('catalogo');?><main class="w"><div class="srnu-page-heading"><div><h1>Receta de insumos</h1><p><?=eh($svc['nombre'])?> · se descuenta al iniciar el trabajo.</p></div><a class="btn light" href="catalogo.php">← Catálogo</a></div><section class="panel" style="padding:18px"><form method="post" class="erp-form cols-3"><input type="hidden" name="id" value="<?=$id?>"><select name="inventario_id" required><option value="">Selecciona insumo</option><?php foreach($inv as $i):?><option value="<?=$i['id']?>"><?=eh($i['nombre'])?> · stock <?=number_format((float)$i['stock'],3)?> <?=eh($i['unidad'])?></option><?php endforeach;?></select><input type="number" step="0.001" min="0.001" name="cantidad" value="1"><button class="btn blue" name="add" value="1">Agregar / actualizar</button></form></section><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Insumo</th><th>Cantidad por servicio</th><th>Stock actual</th><th>Costo estimado</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=eh($r['nombre'])?></td><td><?=number_format((float)$r['cantidad'],3)?> <?=eh($r['unidad'])?></td><td><?=number_format((float)$r['stock'],3)?></td><td><?=emoney((float)$r['cantidad']*(float)$r['costo_unitario'])?></td><td><form method="post"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="row_id" value="<?=$r['id']?>"><button class="btn danger" name="del" value="1">Quitar</button></form></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
